CREATE OR REPLACE VIEW public."conflict_storm_now" AS
 SELECT service,
    session_id,
    tab_id,
    build_id,
    instance,
    user_id,
    record_id,
    model_id,
    reject_reason,
    sum(count) AS conflicts,
    min(first_seen_at) AS first_seen,
    max(last_seen_at) AS last_seen
   FROM conflict_telemetry_buckets
  WHERE (bucket_start >= (now() - '00:01:00'::interval))
  GROUP BY service, session_id, tab_id, build_id, instance, user_id, record_id, model_id, reject_reason
  ORDER BY (sum(count)) DESC
 LIMIT 50;
