CREATE OR REPLACE VIEW public."mos_campaign_v" WITH (security_invoker=true) AS
 SELECT c.id,
    c.ref,
    c.name,
    c.project_id,
    c.objective,
    c.status,
    c.starts_on,
    c.ends_on,
    c.budget_total,
    c.note,
    c.created_by_user_id,
    c.created_at,
    c.updated_at,
    c.archived_at,
    c.kind,
    c.goal,
    c.owner_role,
    c.success_metric,
    c.success_threshold,
    COALESCE(e.exec_count, (0)::bigint) AS execution_count,
    e.total_spend,
    e.total_leads,
    e.total_qualified,
    e.total_impressions,
    e.total_clicks,
    COALESCE(ct.content_count, (0)::bigint) AS content_count
   FROM ((mos_campaigns c
     LEFT JOIN LATERAL ( SELECT count(*) AS exec_count,
            sum(x.spend) AS total_spend,
            sum(x.leads) AS total_leads,
            sum(x.qualified) AS total_qualified,
            sum(x.impressions) AS total_impressions,
            sum(x.clicks) AS total_clicks
           FROM mos_campaign_executions x
          WHERE (x.campaign_id = c.id)) e ON (true))
     LEFT JOIN LATERAL ( SELECT count(*) AS content_count
           FROM mos_content m
          WHERE (m.campaign_id = c.id)) ct ON (true));
CREATE OR REPLACE VIEW public."mos_content_v" WITH (security_invoker=true) AS
 SELECT c.id,
    c.ref,
    c.content_type_id,
    c.workflow_id,
    c.title,
    c.project_id,
    c.campaign_id,
    c.purpose,
    c.language,
    c.goal,
    c.audience,
    c.angle,
    c.cta,
    c.target_publish_at,
    c.due_at,
    c.data,
    c.created_by_user_id,
    c.created_at,
    c.updated_at,
    c.archived_at,
    ct.key AS content_type_key,
    ct.label_ar AS content_type_label_ar,
    ct.label_en AS content_type_label_en,
    t.id AS open_task_id,
    t.role AS owner_role,
    t.assignee_user_id AS current_assignee_user_id,
    t.due_at AS current_task_due_at,
    t.round AS current_round,
    s.key AS current_step_key,
    s.label_ar AS current_step_label_ar,
    s.label_en AS current_step_label_en,
    s."position" AS current_step_position,
        CASE
            WHEN (s.key IS NOT NULL) THEN s.key
            WHEN (t.id IS NOT NULL) THEN 'unassigned'::text
            WHEN (tc.total_tasks > 0) THEN 'done'::text
            ELSE 'draft'::text
        END AS status_key
   FROM ((((mos_content c
     JOIN mos_content_types ct ON ((ct.id = c.content_type_id)))
     LEFT JOIN mos_tasks t ON (((t.content_id = c.id) AND (t.status = 'open'::text))))
     LEFT JOIN mos_workflow_steps s ON ((s.id = t.step_id)))
     LEFT JOIN LATERAL ( SELECT count(*) AS total_tasks
           FROM mos_tasks tt
          WHERE (tt.content_id = c.id)) tc ON (true));
CREATE OR REPLACE VIEW public."mos_publication_v" WITH (security_invoker=true) AS
 SELECT p.id,
    p.content_id,
    p.platform,
    p.account_id,
    p.status,
    p.scheduled_at,
    p.published_at,
    p.caption,
    p.file_id,
    p.external_url,
    p.external_id,
    p.published_by_user_id,
    p.note,
    p.created_at,
    p.updated_at,
    a.label_ar AS account_label_ar,
    a.label_en AS account_label_en,
    a.handle AS account_handle,
    a.is_connected AS account_connected,
    s.captured_at AS latest_captured_at,
    s.source AS latest_source,
    s.views AS latest_views,
    s.engagement AS latest_engagement,
    s.enquiries AS latest_enquiries,
    ( SELECT count(*) AS count
           FROM mos_metric_snapshots x
          WHERE (x.publication_id = p.id)) AS snapshot_count
   FROM ((mos_publications p
     LEFT JOIN mos_platform_accounts a ON ((a.id = p.account_id)))
     LEFT JOIN LATERAL ( SELECT m.id,
            m.publication_id,
            m.captured_at,
            m.source,
            m.views,
            m.engagement,
            m.enquiries,
            m.extra,
            m.entered_by_user_id,
            m.created_at
           FROM mos_metric_snapshots m
          WHERE (m.publication_id = p.id)
          ORDER BY m.captured_at DESC
         LIMIT 1) s ON (true));
