CREATE OR REPLACE VIEW public."v_all_projects_geo_integrity" WITH (security_invoker=true) AS
 WITH ap AS (
         SELECT r.id,
            (r.data ->> 'project_name'::text) AS project_name,
            (NULLIF((r.data ->> 'latitude'::text), ''::text))::double precision AS lat,
            (NULLIF((r.data ->> 'longitude'::text), ''::text))::double precision AS lng,
            NULLIF(((r.data -> 'location'::text) ->> 'district'::text), ''::text) AS stored_district_id,
            NULLIF(((r.data -> 'location'::text) ->> 'city'::text), ''::text) AS stored_city_id,
            NULLIF((r.data ->> 'geo_source'::text), ''::text) AS geo_source
           FROM (records r
             JOIN models m ON ((m.id = r.model_id)))
          WHERE (m.name = 'all_projects'::text)
        )
 SELECT ap.id,
    ap.project_name,
    ap.lat,
    ap.lng,
    ap.stored_district_id,
    ap.stored_city_id,
    ap.geo_source,
    (poly.district_record_id)::text AS polygon_district_id,
    poly.city_id AS polygon_city_id,
        CASE
            WHEN ((ap.lat IS NULL) OR (ap.lng IS NULL)) THEN
            CASE
                WHEN (ap.stored_district_id IS NOT NULL) THEN 'unverified_no_coords'::text
                ELSE 'no_geography'::text
            END
            WHEN (poly.district_record_id IS NULL) THEN 'outside_known_districts'::text
            WHEN (ap.stored_district_id IS NULL) THEN 'verified_derived'::text
            WHEN (ap.stored_district_id = (poly.district_record_id)::text) THEN 'verified_match'::text
            ELSE 'mismatch'::text
        END AS geo_status,
        CASE
            WHEN ((ap.lat IS NOT NULL) AND (ap.lng IS NOT NULL) AND (poly.district_record_id IS NOT NULL) AND ((ap.stored_district_id IS NULL) OR (ap.stored_district_id = (poly.district_record_id)::text))) THEN 'high'::text
            WHEN (((ap.lat IS NULL) OR (ap.lng IS NULL)) AND (ap.stored_district_id IS NOT NULL)) THEN 'medium'::text
            ELSE 'low'::text
        END AS geo_confidence
   FROM (ap
     LEFT JOIN LATERAL ( SELECT b.district_record_id,
            b.city_id
           FROM district_boundaries b
          WHERE (b.is_active AND (ap.lat IS NOT NULL) AND (ap.lng IS NOT NULL) AND st_contains(b.geom, st_setsrid(st_makepoint(ap.lng, ap.lat), 4326)))
         LIMIT 1) poly ON (true));
