CREATE OR REPLACE VIEW public."workflow_runner_action_support" WITH (security_invoker=true) AS
 WITH acts AS (
         SELECT w.id AS workflow_id,
            COALESCE(w.label_en, w.label_ar) AS workflow_name,
            w.trigger_model_id AS model_id,
            w.trigger_event,
            w.is_active,
            (a.value ->> 'id'::text) AS action_id,
            (a.value ->> 'type'::text) AS action_type
           FROM workflows w,
            LATERAL jsonb_array_elements(COALESCE(w.branches, '[]'::jsonb)) br(value),
            LATERAL jsonb_array_elements(COALESCE((br.value -> 'actions'::text), '[]'::jsonb)) a(value)
        UNION
         SELECT w.id,
            COALESCE(w.label_en, w.label_ar) AS "coalesce",
            w.trigger_model_id,
            w.trigger_event,
            w.is_active,
            (a.value ->> 'id'::text),
            (a.value ->> 'type'::text)
           FROM workflows w,
            LATERAL jsonb_array_elements(COALESCE(w.actions, '[]'::jsonb)) a(value)
        )
 SELECT DISTINCT workflow_id,
    workflow_name,
    model_id,
    trigger_event,
    is_active,
    action_id,
    action_type,
        CASE
            WHEN (action_type = ANY (ARRAY['create_record'::text, 'update_record'::text, 'send_whatsapp_message'::text])) THEN 'supported'::text
            ELSE 'unsupported_in_runner_v1'::text
        END AS runner_support_status
   FROM acts;
